css:
body { margin: 0; font-family: Lato; font-size: 16px; }
html { background: #f3e8cc; }
body { margin: 0; font: 16px/20px Lato; color: #22160d; }
p { position: absolute; left: 40px; margin: 0; }:where(sv-top-layer) { display: block; position: fixed; left: 0; top: 0; right: 0; bottom: 0; z-index: 2147483647; pointer-events: none; }
:where(sv-top-layer > *) { position: absolute; }
:where(sv-tooltip) {
    display: block; box-sizing: content-box; padding: 3px 7px 4px; border: 1px solid rgb(60, 60, 60); background-color: white;
    color: rgb(60, 60, 60); font: 12px sans-serif; white-space: pre-wrap; overflow-wrap: break-word; pointer-events: none;
}sv-tooltip { padding: 11px 13px; border: 1px solid #6e5538; color: #f0dcb4; background: linear-gradient(180deg, #4a3624, #2a1d14); font: 400 14px/1.6 Lato; border-radius: 2px; box-shadow: 0 10px 30px #000000b0; }

